/* Local design prototype. All data is synthetic; no device/network/file operations. */
'use strict';
const $ = s => document.querySelector(s);
const esc = s => String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={
 photo:'<rect x="3" y="3" width="18" height="18" rx="3"/><circle cx="8" cy="8" r="1.3"/><path d="m3 17 6-6 4 4 3-3 5 5"/>',
 folder:'<path d="M3 7a2 2 0 0 1 2-2h5l2 2h7a2 2 0 0 1 2 2v10a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2Z"/>',
 shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6Z"/><path d="m8 12 3 3 5-6"/>',
 transfer:'<path d="M7 21V3m-4 4 4-4 4 4M17 3v18m-4-4 4 4 4-4"/>',
 device:'<rect x="6" y="2" width="12" height="20" rx="3"/><path d="M10 18h4M10 5h4"/>',
 settings:'<path d="m9 3-1 3-3 1-2 4 2 3v4l4 2 3-1 3 1 4-2v-4l2-3-2-4-3-1-1-3Z"/><circle cx="12" cy="12" r="3"/>',
 check:'<path d="m5 12 4 4L19 6"/>',
 alert:'<path d="m12 3 10 18H2Z"/><path d="M12 9v4m0 4v.1"/>',
 clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
 refresh:'<path d="M20 8a8 8 0 1 0 0 9M20 3v6h-6"/>',
 pause:'<path d="M8 5v14M16 5v14"/>',
 play:'<path d="m7 4 14 8-14 8Z"/>',
 plus:'<path d="M12 4v16M4 12h16"/>',
 arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',
 back:'<path d="m15 5-7 7 7 7"/>',
 chevron:'<path d="m9 5 7 7-7 7"/>',
 down:'<path d="m5 9 7 7 7-7"/>',
 more:'<circle cx="4" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="20" cy="12" r="1"/>',
 close:'<path d="m6 6 12 12M6 18 18 6"/>',
 wifi:'<path d="M2 8a15 15 0 0 1 20 0M5 12a10 10 0 0 1 14 0M8 16a5 5 0 0 1 8 0"/><circle cx="12" cy="20" r=".8"/>',
 cloud:'<path d="M6 18a5 5 0 1 1 1-10 6 6 0 0 1 11 1 4.5 4.5 0 1 1 0 9Z"/>',
 info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v.1"/>',
 heat:'<path d="M9 14V5a3 3 0 0 1 6 0v9a5 5 0 1 1-6 0Z"/><path d="M12 7v11"/>',
 drive:'<path d="m5 4-3 11v5h20v-5L19 4Z"/><path d="M2 15h20m-5 3h2"/>',
 laptop:'<rect x="4" y="3" width="16" height="13" rx="2"/><path d="m4 16-2 5h20l-2-5"/>',
 motion:'<circle cx="12" cy="12" r="3"/><circle cx="12" cy="12" r="6"/><circle cx="12" cy="12" r="9" stroke-dasharray="2 2"/>',
 burst:'<rect x="6" y="6" width="15" height="15" rx="2"/><path d="M3 17V3h14"/>',
 scan:'<path d="M3 8V3h5m8 0h5v5m0 8v5h-5M8 21H3v-5M6 12h12"/>',
 qr:'<path d="M3 3h6v6H3Zm12 0h6v6h-6ZM3 15h6v6H3Zm11-1h3v3h-3Zm6 0h1v3m-7 4h3v-1m3 1h1m-9-16v4m0 3h-2M3 12h3m4 1v3"/>',
 upload:'<path d="M12 17V3m-5 5 5-5 5 5M3 15v6h18v-6"/>',
 sort:'<path d="M7 20V4m-4 4 4-4 4 4m4 2h6m-6 5h4m-4 5h2"/>',
 archive:'<path d="M3 3h18v4H3Zm1 4v14h16V7m-11 4h6"/>',
 lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V6a4 4 0 0 1 8 0v4m-4 5v2"/>'
};
const icon = n => `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[n]||paths.photo}</svg>`;
const btn=(text,action,ic='',cls='')=>`<button class="btn ${cls}" data-action="${action}">${ic?icon(ic):''}${text}</button>`;
const textbtn=(text,action,ic='')=>`<button class="text-btn" data-action="${action}">${text}${ic?icon(ic):''}</button>`;
const toggle=(label,on=true)=>`<button class="switch ${on?'on':''}" role="switch" aria-checked="${on}" aria-label="${esc(label)}" data-action="toggle"></button>`;
const pill=(text,kind='neutral',ic='')=>`<span class="pill ${kind}">${ic?icon(ic):''}${text}</span>`;
const notice=(title,body='',kind='info',action='')=>`<div class="notice ${kind}">${icon(kind==='error'||kind==='warning'?'alert':'info')}<div class="grow">${title}${body?`<p>${body}</p>`:''}${action}</div></div>`;
const meter=(pct,cls='')=>`<div class="meter ${cls}"><span style="width:${pct}%"></span></div>`;
const navigation={mac:[['library','系统图库','photo'],['folders','文件夹','folder'],['backup','备份概览','shield'],['transfers','传输任务','transfer'],['receiver','接收设备','device'],['settings','设置','settings']],ios:[['library','图库','photo'],['backup','备份','shield'],['receiver','设备','device'],['settings','设置','settings']],android:[['receive','接收','device'],['transfers','传输','transfer'],['storage','存储','drive'],['settings','设置','settings']],web:[['overview','总览','shield'],['transfers','传输记录','transfer'],['storage','存储','drive'],['settings','设置','settings']]};
const defaults={mac:'backup',ios:'backup',android:'receive',web:'overview'};
const state={platform:'mac',page:'backup',scene:'active',review:'screens',filter:'all',folder:false,tree:false,sort:'new',selected:new Set(),selecting:false,tablePage:1,pageSize:20,query:'',small:false,material:'platform',reducedTransparency:false,modal:null};
const queryParams=new URLSearchParams(location.search);
if(navigation[queryParams.get('platform')]){state.platform=queryParams.get('platform');state.page=defaults[state.platform]}
if(navigation[state.platform].some(n=>n[0]===queryParams.get('page'))||(state.platform==='ios'&&queryParams.get('page')==='transfers'))state.page=queryParams.get('page');
if(queryParams.get('size')==='small')state.small=true;
if(queryParams.get('material')==='solid')state.material='solid';
if(queryParams.get('transparency')==='reduced')state.reducedTransparency=true;
if(queryParams.get('review')==='system'||queryParams.get('review')==='motion')state.review=queryParams.get('review');
if(queryParams.get('theme')==='dark'){document.documentElement.dataset.theme='dark';$('.review-theme span').textContent='浅色'}
if(queryParams.get('view')==='app')document.body.classList.add('review-view-only');
const scenes={active:'正在传输',done:'本批已保存',empty:'首次使用 / 空白',loading:'加载中',offline:'接收端未连接',error:'保存到相册失败',thermal:'高温暂停',paused:'手动暂停',disk:'SD 卡已拔出'};
if(scenes[queryParams.get('scene')])state.scene=queryParams.get('scene');
const samples=Array.from({length:248},(_,i)=>({id:i,name:`IMG_${String(5442-i).padStart(4,'0')}.${i%5===2?'MOV':i%5===0?'HEIC':'JPG'}`,kind:i%7===3?'连拍':i%5===2?'视频':i%3===0?'实况':'照片',size:i%5===2?'48.2 MB':i%3===0?'12.6 MB':'4.8 MB',date:`2026/10/02 ${String(12-Math.floor(i/60)).padStart(2,'0')}:${String(59-i%60).padStart(2,'0')}`,status:i<2?'failed':i<5?'receiving':i===5?'received':i<8?'queued':'saved',thumb:i%6,modifiedDate:`2026/10/02 ${String(14-Math.floor(i/60)).padStart(2,'0')}:${String(59-i%60).padStart(2,'0')}`}));
const statusData={saved:['已保存到相册','ok','check'],failed:['相册处理失败','bad','alert'],receiving:['接收中','live','transfer'],queued:['等待接收','neutral','clock'],received:['已接收 · 待处理','warn','clock']};
function fileStatus(f){if(state.scene==='done')return 'saved';if(state.scene==='offline'&&f.status==='receiving')return 'queued';return f.status}
function filePill(f){return pill(...statusData[fileStatus(f)])}
function row(f,compact=false,folder=false){return `<button class="file-row" data-file="${f.id}"><span class="thumb n${f.thumb}"></span><span class="grow"><span class="file-title">${f.name}</span><p>${compact?'10/02 '+f.date.slice(-5):(folder?'修改于 '+f.modifiedDate:'拍摄于 '+f.date)} · ${f.kind}${f.kind==='视频'?' · 00:18':''}</p></span><span class="file-right">${filePill(f)}${!compact?`<span class="size">${f.size}</span>`:''}</span></button>`}
function filtered(){let data=samples.filter(f=>state.filter==='all'||(state.filter==='failed'&&fileStatus(f)==='failed')||(state.filter==='saved'&&fileStatus(f)==='saved')||(state.filter==='receiving'&&['receiving','queued','received'].includes(fileStatus(f))));if(state.query)data=data.filter(f=>f.name.toLowerCase().includes(state.query.toLowerCase()));if(state.sort==='old')data=data.toReversed();if(state.sort==='name')data=[...data].sort((a,b)=>a.name.localeCompare(b.name));return data}
function chips(){return `<div class="chips">${[['all','全部'],['receiving','进行中'],['failed',state.scene==='done'?'失败 · 0':'失败 · 2'],['saved','已保存']].map(([v,t])=>`<button class="chip ${state.filter===v?'active':''}" data-filter="${v}">${t}</button>`).join('')}</div>`}
function sortControl(){return `<label class="small muted">${icon('sort')}<select class="compact-select" data-control="sort" aria-label="文件排序"><option value="new" ${state.sort==='new'?'selected':''}>修改时间：新到旧</option><option value="old" ${state.sort==='old'?'selected':''}>修改时间：旧到新</option><option value="name" ${state.sort==='name'?'selected':''}>文件名：A → Z</option></select></label>`}
function duckMark(){return '<span class="duck-mark" aria-hidden="true"><img src="../../assets/AppIcon.png" alt=""></span>'}
function empty(title,body,action,ic='photo'){return `<div class="empty">${state.scene==='empty'?duckMark():`<div class="empty-art">${icon(ic)}</div>`}<h3>${title}</h3><p>${body}</p>${action}</div>`}
function skeleton(){return `<div class="notice">${icon('clock')}正在读取本机记录…</div>${Array.from({length:7},()=>`<div class="file-row" aria-hidden="true"><div class="skeleton square"></div><div class="grow"><div class="skeleton line"></div><div class="skeleton line short"></div></div><div class="skeleton" style="width:60px;height:12px"></div></div>`).join('')}${textbtn('演示加载完成','loaded')}`}
function activity(mode=state.scene){const d={active:[state.platform==='android'?'正在从 iPhone 接收':'正在传输到 Pixel XL','4 个文件进行中 · 12.8 MB/s','transfer',96],done:['本批文件已保存到 Pixel 相册','248 个文件 · Google 相册云端状态请在相册中确认','check',0],empty:['等待连接接收设备','配对后即可开始备份','device',0],loading:['正在读取任务记录','文件列表加载中','clock',0],paused:[state.platform==='android'?'接收已暂停':'传输已暂停','点继续恢复，已接收原件保留','pause',96],offline:[state.platform==='android'?'接收服务未启动':'等待 Pixel XL 重新连接',state.platform==='android'?'点连接新设备启动接收':'连接恢复后继续传输','wifi',0],error:['2 个文件未保存到 Pixel 相册','原件仍保留在 Pixel，可重试处理','alert',96],thermal:['Pixel 正在降温','43.0 °C · 降至 38 °C 且系统热保护解除后继续','heat',96],disk:['SD 卡未连接','插回 Canon R62 后重新扫描','drive',0]}[mode];return `<div class="activity"><span class="activity-mark ${['thermal','error','disk'].includes(mode)?'warn':''}">${icon(d[2])}</span><div class="grow"><strong>${d[0]}</strong><p>${d[1]}</p></div>${textbtn(mode==='error'?'查看失败':'查看任务','go-transfers')}${meter(d[3])}</div>`}
function intro(){return `<div class="review-intro"><div><div class="eyebrow">BackupDuck · Visual direction</div><h1>让回忆安心抵达。</h1><p>同一个品牌，四种使用场景。先看懂，再操作。</p></div><div class="platforms" aria-label="平台">${[['mac','macOS'],['ios','iOS'],['android','Android'],['web','浏览器']].map(([v,t])=>`<button class="${state.platform===v?'active':''}" data-platform="${v}">${t}</button>`).join('')}</div></div><div class="review-controls"><span>状态预览</span><select data-control="scene" aria-label="预览状态">${Object.entries(scenes).map(([v,t])=>`<option value="${v}" ${state.scene===v?'selected':''}>${t}</option>`).join('')}</select>${['mac','ios'].includes(state.platform)?`<label class="material-control">材质 <select data-control="material" aria-label="材质预览"><option value="platform" ${state.material==='platform'?'selected':''}>平台材质</option><option value="solid" ${state.material==='solid'?'selected':''}>旧系统实色</option></select></label><label class="transparency-control"><input type="checkbox" data-control="transparency" ${state.reducedTransparency?'checked':''}>减少透明度</label>`:''}${state.platform==='android'?`<button class="chip ${state.small?'active':''}" data-action="small">${state.small?'320 × 640 小屏':'切换 320 小屏'}</button>`:''}<span class="spacer"></span><span class="dimensions">${state.platform==='mac'?'原生窗口 · 信息密度优先':state.platform==='web'?'桌面管理 · 表格与详情分层':state.platform==='ios'?'390 × 812 · 发送端':'360 × 720 · 接收端'}</span><span class="pill neutral">交互原型 · 示例数据</span></div>`}
function side(){const web=state.platform==='web';return `<aside class="side">${web?'':'<div class="traffic" aria-hidden="true"><i></i><i></i><i></i></div>'}<div class="brand"><img src="../../assets/AppIcon.png" alt="">备份鸭</div>${navigation[state.platform].map(([v,t,ic],i)=>`${!web&&[0,2,4].includes(i)?`<div class="nav-label">${i===0?'来源':i===2?'备份任务':'管理'}</div>`:web&&i===0?'<div class="nav-label">PIXEL 接收端</div>':''}<button class="nav-item ${state.page===v?'active':''}" data-page="${v}">${icon(ic)}${t}${v==='transfers'&&state.scene==='error'?'<span class="badge">2</span>':''}</button>`).join('')}<div class="side-foot"><div class="line">${icon('device')}Pixel XL ${pill(state.scene==='offline'?'未连接':'在线',state.scene==='offline'?'neutral':'ok')}</div>${state.scene==='offline'?'连接恢复后更新状态':web?'本地网络管理':'通过同一 Wi-Fi 连接'}<br>${state.scene==='offline'?'最近在线：今天 12:40':'温度 37.2 °C · 可用 22.4 GB'}</div></aside>`}
function tabs(){return `<nav class="bottom-tabs" aria-label="主导航">${navigation[state.platform].map(([v,t,ic])=>`<button class="tab ${state.page===v||state.page==='transfers'&&v==='backup'&&state.platform==='ios'?'active':''}" data-page="${v}">${`<span class="tab-icon">${icon(ic)}</span>`}${t}</button>`).join('')}</nav>`}
function pageTitle(){return navigation[state.platform].find(n=>n[0]===state.page)?.[1]||(state.page==='transfers'?'传输任务':'备份鸭')}
function pageHead(){return `<header class="app-header"><h2>${pageTitle()}</h2><div class="head-actions">${state.platform==='mac'||state.platform==='web'?pill(state.scene==='offline'?'Pixel 未连接':'Pixel XL 在线',state.scene==='offline'?'neutral':'ok',state.scene==='offline'?'wifi':'check'):''}${state.page==='library'?textbtn(state.selecting?'完成':'选择','select'):state.page==='folders'&&!state.folder?btn('添加文件夹','add-folder','plus'):state.page==='receive'?`<button class="icon-btn" aria-label="接收帮助" data-action="receive-help">${icon('info')}</button>`:''}</div></header>`}
function render(){document.documentElement.dataset.material=state.reducedTransparency||state.material==='solid'?'solid':'platform';document.querySelectorAll('[data-review]').forEach(b=>b.classList.toggle('active',b.dataset.review===state.review));if(state.review!=='screens'){$('#review').innerHTML=state.review==='system'?systemGuide():motionGuide();return}const phone=['ios','android'].includes(state.platform);$('#review').innerHTML=intro()+`<div class="stage">${phone?`<div class="phone-stage"><section class="phone ${state.platform} ${state.page==='transfers'?'has-activity':''} ${state.small?'small-phone':''}" aria-label="${state.platform} 页面原型"><div class="statusbar"><span>9:41</span><span>◔ ▰</span></div>${pageHead()}<div class="app-scroll"><div class="content">${pageContent()}</div></div>${['transfers'].includes(state.page)?activity():''}${tabs()}${state.platform==='android'?'<div class="system-nav" aria-hidden="true">◁　 ○　 ▢</div>':''}<div id="modal-host"></div></section>${phoneNotes()}</div>`:`<section class="window ${state.platform}" aria-label="${state.platform} 页面原型">${side()}<div class="workspace">${pageHead()}<div class="app-scroll"><div class="content">${pageContent()}</div></div>${state.platform==='mac'?activity():''}</div><div id="modal-host"></div></section>`}<div class="review-footnote"><span>设计提案 v1.1 · 示例数据。材质仅为网页示意，原生由系统组件提供。</span><span>试试导航、状态切换、文件详情、配对和备份规则。</span></div></div>`;if(state.modal)renderModal();}
function pageContent(){if(state.page==='settings')return settingsPage();if(state.page==='storage')return storagePage();if(state.page==='receiver')return receiverPage();if(state.page==='receive')return receivePage();if(state.page==='transfers')return transfersPage();if(state.page==='library')return libraryPage();if(state.page==='folders')return foldersPage();if(state.page==='overview')return webOverview();return backupPage()}
function sceneNotice(){if(state.scene==='offline')return notice('Pixel XL 未连接','确认接收端已启动，并让两台设备连接同一 Wi-Fi。','warning',textbtn('检查连接','connection'));if(state.scene==='thermal')return notice('接收端高温，已暂停接收','电池温度 43.0 °C。降至 38 °C 且系统热保护解除后自动继续。','warning',textbtn('查看温度保护','thermal-settings'));if(state.scene==='error')return notice('2 个文件保存到相册失败','原件安全保留在 Pixel。重试只处理失败文件。','error',textbtn('查看失败','failed'));if(state.scene==='disk')return notice('Canon R62 未连接','扫描没有完成。插回 SD 卡后再扫描，已有备份记录会保留。','warning',textbtn('重新扫描','scan'));return ''}
function backupPage(){const mobile=state.platform==='ios';if(state.scene==='empty')return empty('给回忆多一个家','先连接 Pixel 接收端，再备份系统图库中的照片和视频。',btn('连接接收设备','go-receiver','device','primary'),'shield');if(state.scene==='loading')return skeleton();return `<div class="${mobile?'':'section-head backup-context'}"><div><h3 class="${mobile?'subtitle':'big-title'}">${state.scene==='done'?'本批已保存':'今天的备份'}</h3>${mobile?'': '<p class="subtitle">10 月 2 日 · 2 个来源</p>'}</div>${mobile?'':btn('选择照片','go-library','photo')}</div>${sceneNotice()}<div class="hero"><div class="backup-card"><div class="row between"><h3>${state.scene==='done'?'本批已保存':'本批备份进度'}</h3>${pill(state.scene==='done'?'已保存':'进行中',state.scene==='done'?'ok':'live')}</div><div class="count"><strong>${state.scene==='done'?'248':'240'}</strong><span>/ 248 个文件已保存到 Pixel 相册</span></div>${meter(state.scene==='done'?100:96.8)}<div class="backup-meta"><span>${state.scene==='done'?'全部已保存':'6 个进行中 · 2 个失败'}</span><span>${state.scene==='active'?'12.8 MB/s':'状态已更新'}</span></div><div class="row">${btn(state.scene==='active'?'暂停传输':'继续备份',state.scene==='active'?'pause':'resume',state.scene==='active'?'pause':'play','primary')}${btn('传输任务','go-transfers','transfer')}</div></div>${mobile?'':deviceCard()}</div><div class="section-head"><h3>备份来源</h3>${textbtn('管理来源',mobile?'go-settings':'go-folders','chevron')}</div><div class="source-list summary-sources"><div class="source-row"><div class="source-icon">${icon('photo')}</div><div class="grow"><h4>系统图库</h4><p>照片、实况、视频与连拍</p></div><div class="stack"><span class="small muted">自动备份</span>${toggle('系统图库自动备份')}</div></div>${mobile?'':`<div class="source-row"><div class="source-icon">${icon('folder')}</div><div class="grow"><h4>文件夹</h4><p>Canon R62 · ~/Pictures · 2 个来源</p></div>${textbtn('查看','go-folders','chevron')}</div>`}</div><div class="section-head"><h3>最近传输</h3>${textbtn('全部','go-transfers','chevron')}</div><div class="file-list">${samples.slice(state.scene==='error'?0:8,mobile?11:12).map(f=>row(f,mobile)).join('')}</div><div class="cloud-note">${icon('cloud')}“已保存”表示文件已加入 Pixel 相册。云端备份请在 Google 相册确认。</div>`}
function deviceCard(){return `<div class="device-card"><div class="row between"><div class="device-symbol">${icon('device')}</div>${pill('在线','ok')}</div><h4>Pixel XL</h4><p class="small muted">同一 Wi-Fi · 连接正常</p><div class="device-readings"><div><strong>37.2 °C</strong><span>电池温度</span></div><div><strong>22.4 GB</strong><span>可用空间</span></div></div>${textbtn('设备详情','go-receiver','chevron')}</div>`}
function libraryPage(){if(state.scene==='empty')return empty('允许访问照片','备份鸭需要读取照片，才能浏览并备份。原件不会被修改。',btn('允许访问照片','permission','photo','primary'));if(state.scene==='loading')return skeleton();return `<div class="section-head"><div><h3 class="${state.platform==='ios'?'':'big-title'}">今天</h3><p class="subtitle">10 月 2 日 · 18 个项目</p></div>${state.platform==='mac'?btn(state.selecting?'完成':'选择照片','select','photo'):''}</div><div class="row between" style="margin:15px 0">${pill('已保存到 Pixel 相册','ok','check')}${textbtn('状态说明','status-guide','info')}</div><div class="gallery ${state.selecting?'selecting':''}">${samples.slice(8,26).map((f,i)=>`<button class="photo n${f.thumb} ${state.selected.has(f.id)?'selected':''}" data-photo="${f.id}" aria-label="${f.name}，${f.kind}，拍摄于 ${f.date}，${statusData[fileStatus(f)][0]}"><span class="select-circle">${state.selected.has(f.id)?icon('check'):''}</span><span class="photo-state ${fileStatus(f)==='saved'?'':'warn'}">${icon(statusData[fileStatus(f)][2])}</span>${f.kind==='照片'?'':`<span class="photo-kind">${icon(f.kind==='实况'?'motion':f.kind==='连拍'?'burst':'play')}${f.kind==='视频'?'00:18':f.kind==='连拍'?'12 张':'实况'}</span>`}</button>`).join('')}</div>${state.selecting?`<div class="row between" style="margin:18px 0"><span class="small muted">已选 ${state.selected.size} 个项目</span>${btn('备份所选','backup-selected','upload','primary')}</div>`:'<p class="small muted" style="margin-top:14px">点击照片查看详情；右上角标记表示在 Pixel 的保存状态。</p>'}`}
function foldersPage(){if(state.folder)return folderDetail();if(state.scene==='empty')return empty('添加你的第一个文件夹','相机 SD 卡、电脑文件夹或外置硬盘，都可以作为备份来源。',btn('添加文件夹','add-folder','plus','primary'),'folder');if(state.scene==='loading')return skeleton();return `<h3 class="big-title">文件夹</h3><p class="subtitle">备份照片和视频，保留原文件。</p>${sceneNotice()}${[['Canon R62','/Volumes/Canon R62','56 个文件 · 606.1 MB',state.scene==='disk'?'SD 卡未连接':'56 个文件已保存'],['Pictures','~/Pictures','192 个文件 · 1.8 GB','184 个已保存 · 2 个失败']].map(([n,p,c,s],i)=>`<div class="folder-card"><div class="row"><div class="source-icon">${icon('folder')}</div><div class="grow"><h4 class="folder-title">${n}</h4><p class="folder-path">${p}</p></div><button class="icon-btn" aria-label="${n} 更多操作" data-action="folder-menu">${icon('more')}</button></div><div class="folder-stats">${pill(s,i===1?'warn':state.scene==='disk'?'neutral':'ok',i===1?'alert':state.scene==='disk'?'drive':'check')}<span>${c}</span></div><div class="folder-actions">${btn('查看文件','folder-detail','folder')}${btn('备份现有文件','backup-existing','upload')}<span class="folder-auto">自动备份${toggle(n+'自动备份')}</span></div></div>`).join('')}<div class="cloud-note">${icon('info')}“备份现有文件”会跳过已备份且未变化的文件；自动备份负责新增和修改的内容。</div>`}
function folderDetail(){return `<button class="breadcrumb" data-action="folder-back">${icon('back')}文件夹</button><div class="section-head"><div><h3 class="big-title">Canon R62</h3><p class="subtitle">/Volumes/Canon R62 · 56 个文件</p></div>${btn('备份规则','rules','settings')}</div>${sceneNotice()}<div class="row between" style="margin:20px 0">${btn('备份现有文件','backup-existing','upload')}<span class="folder-auto">自动备份${toggle('Canon R62 自动备份')}</span></div><div class="list-head">${sortControl()}<div class="chips"><button class="chip ${!state.tree?'active':''}" data-action="flat">平铺</button><button class="chip ${state.tree?'active':''}" data-action="tree">按文件夹</button></div></div><div class="file-list">${state.tree?`<button class="tree-folder" data-action="tree-expand">${icon(state.treeOpen?'down':'chevron')}${icon('folder')}DCIM<span class="muted">56 个文件</span></button>${state.treeOpen?`<div class="tree-children"><div class="tree-folder">${icon('down')}${icon('folder')}100EOSR6</div>${filtered().slice(8,14).map(f=>row(f,false,true)).join('')}</div>`:''}`:filtered().slice(8,16).map(f=>row(f,false,true)).join('')}</div><p class="small muted" style="margin-top:15px">文件时间按当前排序字段显示。未备份项目在“传输任务 → 失败”查看。</p>`}
function transfersPage(){if(state.scene==='empty')return empty('还没有传输记录','开始一次备份，文件的传输与相册处理状态会出现在这里。',btn(state.platform==='android'?'开始接收':'开始备份',state.platform==='android'?'start':'go-backup','play','primary'),'transfer');if(state.scene==='loading')return skeleton();const mobile=['ios','android'].includes(state.platform);return `${state.platform==='ios'?'<button class="breadcrumb" data-page="backup">'+icon('back')+'备份</button>':''}${!mobile?`<div class="section-head"><div><h3 class="big-title">${state.platform==='web'?'传输记录':'传输任务'}</h3><p class="subtitle">文件到达哪里，清楚看见。</p></div>${textbtn('状态说明','status-guide','info')}</div>`:`<div class="row between small muted"><span>248 个项目 · ${state.scene==='done'?'248':'240'} 个已保存</span>${textbtn('状态说明','status-guide','info')}</div>`}${sceneNotice()}<div class="list-head">${chips()}${!mobile?`<input class="search" data-control="search" aria-label="查找文件名" placeholder="查找文件名…" value="${esc(state.query)}">`:''}</div>${state.platform==='web'?table():`<div class="file-list">${filtered().slice(0,mobile?22:18).map(f=>row(f,mobile)).join('')||empty('没有匹配的文件','试试其他筛选条件。',textbtn('显示全部','clear-filter'),'photo')}</div>`}`}
function table(){const data=filtered();const total=Math.max(1,Math.ceil(data.length/state.pageSize));state.tablePage=Math.min(total,state.tablePage);const start=(state.tablePage-1)*state.pageSize;return `<div class="table-wrap history-table"><table class="data-table"><thead><tr><th>文件</th><th>状态</th><th>拍摄时间</th><th>大小</th></tr></thead><tbody>${data.slice(start,start+state.pageSize).map(f=>`<tr><td><div class="table-file"><span class="thumb n${f.thumb}"></span><div><button data-file="${f.id}">${f.name}</button><p>${f.kind}${f.kind==='视频'?' · 00:18':''}</p></div></div></td><td>${filePill(f)}</td><td>${f.date}</td><td>${f.size}</td></tr>`).join('')||'<tr><td colspan="4">没有匹配的文件。</td></tr>'}</tbody></table></div><div class="pagination"><div>共 ${data.length} 项 · <select class="compact-select" data-control="page-size" aria-label="每页条数">${[20,50,100].map(n=>`<option ${state.pageSize===n?'selected':''}>${n}</option>`).join('')}</select> 项/页</div><div class="page-buttons"><button data-table-page="1" ${state.tablePage===1?'disabled':''} aria-label="第一页">«</button><button data-table-page="${Math.max(1,state.tablePage-1)}" ${state.tablePage===1?'disabled':''} aria-label="上一页">‹</button>${Array.from({length:Math.min(total,5)},(_,i)=>Math.min(Math.max(1,state.tablePage-2),Math.max(1,total-4))+i).map(n=>`<button class="${n===state.tablePage?'active':''}" data-table-page="${n}" aria-label="第 ${n} 页">${n}</button>`).join('')}<button data-table-page="${Math.min(total,state.tablePage+1)}" ${state.tablePage===total?'disabled':''} aria-label="下一页">›</button><button data-table-page="${total}" ${state.tablePage===total?'disabled':''} aria-label="末页">»</button><span style="margin-left:7px">到 <input type="number" min="1" max="${total}" value="${state.tablePage}" data-control="jump-page" aria-label="跳转页数"> 页 / ${total}</span></div></div>`}
function receiverPage(){if(state.scene==='empty'||state.scene==='offline')return `<div class="${state.platform==='ios'?'':'section-head'}"><div><h3 class="big-title">连接你的 Pixel</h3><p class="subtitle">两台设备连接同一 Wi-Fi，配对一次即可。</p></div></div><div class="onboarding-brand">${duckMark()}<span>给回忆多一个家</span></div><div class="connect-steps"><div class="connect-step"><i>1</i><h4>打开接收端</h4><p>在 Pixel 备份鸭中点“连接新设备”。</p></div>${state.platform==='ios'?'':`<div class="connect-step"><i>2</i><h4>扫码配对</h4><p>用 Pixel 扫描 Mac 显示的配对码。</p></div>`}</div>${state.platform==='ios'?btn('扫描 Pixel 配对码','scan-pair','scan','primary'):btn('显示 Mac 配对码','pair','qr','primary')}${notice('找不到接收端？','检查 Wi-Fi、接收开关及本地网络权限。','info',textbtn('连接帮助','connection'))}`;return `<h3 class="big-title">Pixel XL</h3><p class="subtitle">已配对 · 家庭 Wi-Fi</p><div class="hero">${deviceCard()}<div class="backup-card"><h3>连接正常</h3><p class="muted small">通过局域网加密传输。照片和视频发送到这台 Pixel，随后由 Google 相册备份至云端。</p><div class="sep"></div>${btn('测试连接','connection','wifi')}${textbtn('配对其他设备','pair','plus')}</div></div><div class="setting-group"><h3>接收端状态</h3>${setting('保存到相册','240 个成功 · 2 个需要重试',pill('有失败','warn'),'failed')}${setting('可用空间','22.4 GB / 64 GB',pill('充足','ok'))}${setting('电池温度','37.2 °C · 达到 40 °C 暂停接收',pill('正常','ok'))}</div>${notice('关于云端备份','备份鸭可确认 Pixel 已保存文件，不能据此确认 Google 相册云端已上传。')}`}
function receivePage(){if(state.scene==='loading')return skeleton();const idle=state.scene==='empty'||state.scene==='offline';return `<div class="receive-hero ${idle?'first-connect':''}"><div class="row">${idle?duckMark():`<div class="source-icon">${icon('device')}</div>`}<div class="grow"><h3>${idle?'准备连接设备':state.scene==='thermal'?'等待手机降温':state.scene==='paused'?'接收已暂停':'正在接收'}</h3><p>${idle?'Pixel XL · 尚未开始接收':state.scene==='thermal'?'43.0 °C · 已自动暂停':state.scene==='paused'?'点继续恢复接收':'来自 iPhone · 同一 Wi-Fi'}</p></div>${pill(idle?'未启动':state.scene==='thermal'?'暂停':'在线',idle?'neutral':state.scene==='thermal'?'warn':'ok')}</div>${idle?btn('连接新设备','pair','plus','primary'):btn('连接新设备','pair','plus')}</div>${state.scene==='thermal'||state.scene==='error'?sceneNotice():''}<div class="section-head"><h3>${idle?'怎么配对？':'本批接收'}</h3>${idle?'':textbtn('全部记录','go-transfers','chevron')}</div>${idle?`<div class="pair-options"><button class="pair-option" data-action="pair">${icon('qr')}<span class="grow"><strong>连接 iPhone / iPad</strong><p>显示配对码，让 iPhone 扫描</p></span>${icon('chevron')}</button><button class="pair-option" data-action="scan-pair">${icon('scan')}<span class="grow"><strong>连接 Mac</strong><p>用 Pixel 扫描 Mac 的配对码</p></span>${icon('chevron')}</button></div><div class="cloud-note">${icon('info')}选择连接方式后，会自动启动接收服务。</div>`:`<div class="mini-readings"><div><strong>${state.scene==='done'?'248':'240'}</strong><span>已保存到相册</span></div><div><strong>${state.scene==='done'?'0':'6'}</strong><span>进行中</span></div><div><strong style="color:var(--red)">${state.scene==='done'?'0':'2'}</strong><span>处理失败</span></div></div><div class="file-list">${samples.slice(2,5).map(f=>row(f,true)).join('')}</div>${textbtn(state.scene==='paused'?'继续接收':'暂停接收',state.scene==='paused'?'resume':'pause',state.scene==='paused'?'play':'pause')}`}<div class="mini-readings"><div><strong>${state.scene==='thermal'?'43.0':'37.2'} °C</strong><span>电池温度</span></div><div><strong>22.4 GB</strong><span>可用空间</span></div><div><strong>82%</strong><span>电量 · 充电中</span></div></div><div class="cloud-note">${icon('cloud')}已保存到手机相册后，云端备份由 Google 相册继续完成。</div>`}
function setting(title,desc,control,action=''){return `<${action?'button':'div'} class="setting-row" ${action?`data-action="${action}"`:''}><div class="grow"><h4>${title}</h4>${desc?`<p>${desc}</p>`:''}</div>${control||icon('chevron')}</${action?'button':'div'}>`}
function settingsPage(){const receiver=['android','web'].includes(state.platform);return `<p class="subtitle" style="margin-bottom:20px">${receiver?'接收与保存的方式，由你决定。':'按来源选择备份方式。'}</p><div class="settings-grid"><div><div class="setting-group"><h3>${receiver?'接收设置':'备份来源'}</h3>${receiver?setting('重启后自动接收','重新打开备份鸭时恢复接收。',toggle('重启后自动接收')):setting('系统图库','自动备份新增照片、实况、视频与连拍。',toggle('系统图库自动备份'))}${!receiver&&state.platform==='mac'?setting('文件夹','每个文件夹独立设置自动备份和筛选规则。','', 'go-folders'):''}${receiver?setting('温度保护','超过电池温度阈值，暂停新的接收。',toggle('温度保护'))+setting('暂停温度','电池传感器读数；降温后自动恢复。','<span class="value">40 °C</span>','thermal-settings'):setting('仅 Wi-Fi 备份','使用本地网络连接 Pixel。',toggle('仅 Wi-Fi 备份'))}${receiver?setting('兼容转换','仅在原样封装不支持时转换。可能重新编码。',toggle('兼容转换',false)):setting('备份时保持屏幕亮起','仅在应用前台传输时生效。',toggle('备份时保持屏幕亮起',false))}</div><div class="setting-group"><h3>${receiver?'浏览器管理':'显示'}</h3>${receiver?setting('允许浏览器管理','仅在可信任的局域网开启。',toggle('允许浏览器管理',state.platform==='web'))+setting('访问方式','开启后，在电脑输入本机地址和访问码。','', 'web-access'):setting('显示缩略图','按需加载，关闭可减少内存使用。',toggle('显示缩略图'))+setting('文件列表','平铺或按文件夹显示。','<span class="value">平铺</span>','list-view')}</div></div><div><div class="setting-group"><h3>设备与外观</h3>${setting('设备名称',receiver?'Pixel XL':'轻风彗星','', 'rename')}${setting('外观','当前预览支持浅色与深色。','<span class="value">跟随系统</span>','theme')}${setting('语言','','<span class="value">简体中文</span>','language')}</div><div class="setting-group"><h3>帮助与关于</h3>${setting('连接与备份帮助','连接异常、权限和 Google 相册备份。','','connection')}${setting('检查更新','当前示例版本 0.2.0','','updates')}${setting('备份鸭 / BackupDuck','把来源 → Pixel 的备份链路做透。',pill('设计 v1','neutral'))}</div></div></div>`}
function storagePage(){return `<div class="section-head"><div><h3 class="big-title">空间足够，备份安心。</h3><p class="subtitle">Pixel XL · 本机存储</p></div></div><div class="backup-card" style="margin:21px 0"><h3>可用空间</h3><div class="storage-total">22.4 GB <small>/ 64 GB</small></div><div class="storage-bar"><span></span><span></span><span></span></div><div class="storage-legend"><span><i></i>备份鸭原件 11.5 GB</span><span><i></i>处理中 5.1 GB</span><span><i></i>其他 25.0 GB</span></div></div><div class="setting-group"><h3>文件保留</h3>${setting('保留原件','相册处理失败时可从原件重试。',pill('安全保留','ok','archive'))}${setting('原件空间上限','到达上限后暂停接收，不自动删除原件。','<span class="value">16 GB</span>','storage-limit')}${setting('待处理文件','2 个文件处理失败，原件仍在。',pill('2 个','warn'),'failed')}</div>${notice('清理前请确认云端备份','保存到 Pixel 相册不代表云端备份完成。不要依据本页状态删除唯一原件。','warning')}${btn('查看存储明细','storage-detail','drive')}`}
function webOverview(){if(state.scene==='empty'||state.scene==='offline')return empty('连接 Pixel 管理页','在 Pixel 设置中开启浏览器管理，用手机显示的访问码登录。',btn('输入访问码','web-access','lock','primary'),'laptop');if(state.scene==='loading')return skeleton();return `<div class="section-head"><div><div class="eyebrow">Pixel XL / Receiver</div><h3 class="big-title" style="margin-top:5px">接收端总览</h3><p class="subtitle">在大屏幕，照看每一份备份。</p></div><div class="row"><span class="small muted">自动刷新</span>${toggle('自动刷新')}${btn('刷新','refresh','refresh')}</div></div>${sceneNotice()}<div class="stat-grid">${[['已保存到相册',state.scene==='done'?'248':'240','可在 Pixel 图库查看','check'],['进行中',state.scene==='done'?'0':'6',state.scene==='done'?'当前没有等待任务':'接收 3 · 等待 2 · 处理 1','transfer'],['处理失败',state.scene==='done'?'0':'2',state.scene==='done'?'本批没有处理失败':'原件保留，可重新处理','alert'],['可用空间','22.4 GB','电池 37.2 °C · 电量 82%','drive']].map(([t,n,d,ic])=>`<div class="stat-card"><span class="small">${icon(ic)}${t}</span><strong>${n}</strong><p>${d}</p></div>`).join('')}</div><div class="section-head"><h3>最近接收</h3><div class="row">${textbtn('状态说明','status-guide','info')}${btn('重试失败','retry','refresh')}${textbtn('全部记录','go-transfers','chevron')}</div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>文件</th><th>状态</th><th>拍摄时间</th><th>大小</th></tr></thead><tbody>${samples.slice(0,6).map(f=>`<tr><td><div class="table-file"><span class="thumb n${f.thumb}"></span><div><button data-file="${f.id}">${f.name}</button><p>${f.kind}</p></div></div></td><td>${filePill(f)}</td><td>${f.date}</td><td>${f.size}</td></tr>`).join('')}</tbody></table></div><div class="cloud-note">${icon('cloud')}这里展示接收端的本地记录。Google 相册云端备份状态请到相册中确认。</div>`}
function phoneNotes(){const android=state.platform==='android';return `<aside class="phone-note"><div class="note-number">${android?'02 / PIXEL RECEIVER':'01 / IPHONE SENDER'}</div><h3>${android?'旧手机，也要轻松照看备份。':'像整理相册一样，轻松备份。'}</h3><p>${android?'让设备连接成为第一步。接收和相册处理分开表达，温度与空间一眼可见。':'图库沿用熟悉的照片浏览方式，实况、连拍和视频都有独立标识；状态用文字解释。'}</p><ul class="notes-list"><li><span class="number">01</span><div><strong>${android?'不用先理解“开始接收”':'清楚的备份边界'}</strong><span>${android?'连接新设备直接启动接收，再选择显示码或扫描码。':'已保存到 Pixel 相册，不含糊地称作“云端成功”。'}</span></div></li><li><span class="number">02</span><div><strong>${android?'列表优先，详情下沉':'失败有去处'}</strong><span>${android?'接收页看当前任务，传输页每行只留核心信息。':'失败项目集中在任务筛选，详情说明原因与恢复操作。'}</span></div></li><li><span class="number">03</span><div><strong>${android?'密度适配小屏':'操作不过度简写'}</strong><span>${android?'试试 320 小屏，状态区不挤占传输列表。':'用“备份所选”“暂停传输”，避免仅写“备份”“暂停”。'}</span></div></li></ul><button class="btn" data-review="motion">查看动效与稳定布局 ${icon('arrow')}</button></aside>`}
function systemGuide(){return `<div class="guide"><div class="guide-head"><div><div class="eyebrow">Foundations / 01</div><h1>温暖，但不打扰。</h1><p class="lead">鸭子负责亲切，界面负责可靠。品牌黄色点到为止，操作用蓝色，状态用文字和图形共同说明。</p></div><a class="btn" href="specification.md">完整设计标准 ${icon('arrow')}</a></div><div class="guide-grid"><section class="guide-card"><h2>01 · 颜色与语义</h2><p>减少大块鲜艳背景，让照片和重要操作成为视觉中心。</p><div class="swatches">${[['暖白','--canvas','#F5F3EE'],['表面','--surface','#FFFFFF'],['文字','--ink','#202C3E'],['操作','--blue','#165DCE'],['鸭黄','--yellow','#F5C534'],['已保存','--green','#19744C']].map(([t,v,hex])=>`<div class="swatch"><i style="background:var(${v})"></i><strong>${t}</strong>${document.documentElement.dataset.theme==='dark'?getComputedStyle(document.documentElement).getPropertyValue(v).trim().toUpperCase():hex}</div>`).join('')}</div><div class="row" style="flex-wrap:wrap">${pill('已保存到相册','ok','check')}${pill('等待处理','warn','clock')}${pill('保存失败','bad','alert')}</div></section><section class="guide-card full brand-guide"><h2>鸭黄在哪里使用？</h2><p>工作页面让位给照片和任务。鸭黄出现在品牌图标、首次连接与空状态的插画底色；存储页另用它区分文件分类。</p><div class="brand-examples"><div class="brand-example"><div class="brand-example-art">${duckMark()}<span class="brand-spark"></span></div><strong>首次连接 / 空状态</strong><p>小块暖黄衬托鸭子，按钮仍是蓝色。</p><a class="text-btn" href="?platform=android&scene=empty">看首次连接 ${icon('arrow')}</a></div><div class="brand-example"><div class="brand-example-storage"><div class="storage-bar"><span></span><span></span><span></span></div><div class="storage-legend"><span><i></i>原件</span><span><i></i>处理中与派生文件</span></div></div><strong>存储分类</strong><p>黄色仅区分类别，不表示警告或失败。</p><a class="text-btn" href="?platform=android&page=storage">看存储页面 ${icon('arrow')}</a></div><div class="brand-example"><div class="brand-example-status">${pill('等待处理','warn','clock')}${pill('相册处理失败','bad','alert')}</div><strong>状态有自己的语义</strong><p>橙色是提醒、红色是失败；鸭黄不用于状态文字。</p></div></div></section><section class="guide-card"><h2>02 · 排版与空间</h2><div class="type-sample"><h3>回忆，安心抵达。</h3><h4>正在备份到 Pixel XL</h4><p>4 个文件进行中 · 12.8 MB/s</p></div><table class="token-table"><tr><td>页面标题 / 正文 / 辅助</td><td>24–28 / 14–16 / 11–13</td></tr><tr><td>基础间距</td><td>4 · 8 · 12 · 16 · 24 · 32</td></tr><tr><td>圆角：控件 / 容器 / 弹层</td><td>8 / 12–16 / 20</td></tr><tr><td>手机触控目标（原生落地）</td><td>iOS ≥44 pt / Android ≥48 dp</td></tr></table></section><section class="guide-card"><h2>03 · 动作层级</h2><div class="row" style="margin:20px 0;flex-wrap:wrap">${btn('连接新设备','pair','plus','primary')}${btn('查看文件','demo-control','folder')}${textbtn('了解状态','status-guide','info')}</div><p>每个场景只保留一个主要动作。危险操作放详情或更多菜单，并解释影响；“自动备份”是设置，“暂停传输”是当前任务操作。</p><div class="source-list" style="margin:18px 0 0"><div class="source-row"><div class="grow"><h4>自动备份</h4><p>新增和修改的文件自动加入备份</p></div>${toggle('组件自动备份')}</div></div></section><section class="guide-card"><h2>04 · 状态不能只靠颜色</h2><table class="token-table"><tr><td>${pill('接收中','live','transfer')}</td><td>字节正在传输</td></tr><tr><td>${pill('已接收 · 待处理','warn','clock')}</td><td>原件已保存，未加入相册</td></tr><tr><td>${pill('已保存到相册','ok','check')}</td><td>可在 Pixel 系统相册查看</td></tr><tr><td>${pill('相册处理失败','bad','alert')}</td><td>保留原件，提供重试</td></tr></table><p style="margin-top:15px">不显示无依据的“云端已完成”。已保存到相册与 Google 相册云端上传是两个阶段。</p></section><section class="guide-card full"><h2>05 · 统一语言，尊重平台</h2><div class="connect-steps"><div class="connect-step"><i>i</i><h4>iOS / 发送</h4><p>底部四个主入口，浮动导航与工具栏使用系统材质；照片、列表与进度保持清晰实色。</p></div><div class="connect-step"><i>M</i><h4>macOS / 发送</h4><p>侧边栏与工具栏使用系统材质；来源、队列与设置保留熟悉的桌面结构。</p></div><div class="connect-step"><i>P</i><h4>Android / 接收</h4><p>Material 风格的胶囊选中态、按钮与底部弹层；实色表面适合旧 Pixel，保留列表密度。</p></div><div class="connect-step"><i>W</i><h4>浏览器 / 管理</h4><p>核心字段表格、编号分页与单项详情，刷新不打断浏览旧页。</p></div></div><p>原型是视觉与交互契约。实际实现使用 UIKit / AppKit / Android 原生组件；长列表沿用现有分页、缩略图缓存与虚拟化。</p></section><section class="guide-card full"><h2>06 · 材质服务层级，不遮挡内容</h2><div class="material-examples"><div class="material-example apple"><span class="material-example-bar">图库 <span>选择</span></span><div class="material-example-photo"></div><strong>Apple · 导航材质</strong></div><div class="material-example solid"><span class="material-example-bar">传输 <span>筛选</span></span><div class="material-example-photo"></div><strong>Android / 浏览器 · 实色</strong></div></div><p>半透明只用于 Apple 导航、工具栏和标准弹层。内容卡片、错误说明、文件列表与进度不叠玻璃。此处用 CSS 示意层级，不模拟完整 Liquid Glass 光学效果。</p><table class="token-table"><tr><td>旧系统 / 不支持模糊</td><td>同一布局，实色背景与清晰边线</td></tr><tr><td>减少透明度 / 增强对比度</td><td>用不透明表面，保留全部信息与操作</td></tr><tr><td>深色模式</td><td>独立深色材质底色，不降低文字不透明度</td></tr><tr><td>旧 Pixel</td><td>不计算实时模糊、不引入循环装饰动画</td></tr></table><div class="row" style="gap:18px;flex-wrap:wrap;margin-top:18px"><a class="text-btn" href="?platform=ios&page=library">看 iOS 材质 ${icon('arrow')}</a><a class="text-btn" href="?platform=ios&page=library&material=solid">看实色对照 ${icon('arrow')}</a></div></section></div></div>`}
let motionMode='active';
function motionGuide(){return `<div class="guide"><div class="guide-head"><div><div class="eyebrow">Motion / 02</div><h1>变化有反馈，页面不晃动。</h1><p class="lead">动效帮助理解状态变化，不用来掩盖等待。点击演示按钮，比较正在传输、降温、失败和完成。</p></div><a class="btn" href="motion.md">完整动效指南 ${icon('arrow')}</a></div><div class="guide-grid"><section class="guide-card full"><h2>01 · 稳定的任务状态区</h2><p>每种状态都保留标题与解释。进度线附着在容器底边；没有进度时，消除线条，正文显示下一步或最近结果，不留一块空白。</p><div class="motion-demo" id="motion-activity">${activity(motionMode)}</div><div class="motion-controls">${['active','thermal','error','done','offline'].map(v=>`<button class="chip ${motionMode===v?'active':''}" data-motion="${v}">${scenes[v]}</button>`).join('')}</div><div class="timing"><span>容器几何尺寸不变</span><span>文字变化 120 ms 淡入</span><span>进度更新 320 ms</span><span>进度线贴底 · 2 px</span></div></section><section class="guide-card"><h2>02 · 详情与配对弹层</h2><p>手机用底部弹层，桌面用居中对话框。背景淡入，内容轻移 12 px，原页面位置保持不变。</p><div class="motion-stage"><div class="motion-sheet" id="demo-sheet"><h4>文件详情</h4><p>IMG_5442.HEIC · 实况 · 已保存到相册</p></div></div>${btn('打开 / 关闭弹层','motion-sheet','plus')}<div class="timing"><span>进入 220 ms</span><span>退出 160 ms</span><span>曲线 .2 / .8 / .2 / 1</span></div></section><section class="guide-card"><h2>03 · 开关与操作反馈</h2><p>设置先反映已确认的值；异步写入时可显示“保存中”，失败恢复原值并给原因。不依赖短暂提示来报告重要错误。</p><div class="source-list" style="margin-top:20px"><div class="source-row"><div class="grow"><h4>温度保护</h4><p>超过阈值后暂停新接收</p></div>${toggle('动效温度保护')}</div></div><div class="timing"><span>拇指位移 160 ms</span><span>点击反馈 80–120 ms</span><span>错误持续显示</span></div></section><section class="guide-card full"><h2>04 · 克制的边界</h2><table class="token-table"><tr><td>文件列表刷新</td><td>不整表淡出，不自动滚回顶部，不闪缩略图</td></tr><tr><td>温度波动与短暂网络状态</td><td>展示业务已确认的状态，不为每次采样改布局</td></tr><tr><td>首屏加载</td><td>静态骨架，固定缩略图槽位，不循环闪烁</td></tr><tr><td>减少动态效果</td><td>尊重系统开关，取消位移与进度过渡</td></tr><tr><td>旧 Pixel</td><td>不使用模糊实时背景、大面积阴影或循环装饰动画</td></tr></table></section></div></div>`}
let modalTrigger=null;
function openModal(kind,data=null){if(!state.modal)modalTrigger=document.activeElement;state.modal={kind,data};if(!$('#modal-host')){showToast('在页面原型里可查看该操作。');state.modal=null;return}renderModal()}
function modalContent(kind,data){if(kind==='detail'){const f=samples[data],stage=fileStatus(f),hasOriginal=['received','saved','failed'].includes(stage);return ['文件详情',`<div class="detail-preview" style="background-position:${f.thumb%3*50}% ${f.thumb>2?100:0}%"></div><div class="row between"><h4>${f.name}</h4>${filePill(f)}</div><dl class="detail-grid"><dt>类型</dt><dd>${f.kind}${f.kind==='视频'?' · 00:18':''}</dd><dt>拍摄时间</dt><dd>${f.date}</dd><dt>来源设备</dt><dd>iPhone · 轻风彗星</dd><dt>大小</dt><dd>${f.size}</dd><dt>原件</dt><dd>${hasOriginal?'保留在 Pixel，可重试处理':'接收尚未完成'}</dd></dl><ul class="timeline"><li class="${hasOriginal?'':'pending'}">${hasOriginal?'已接收原件':stage==='queued'?'等待接收原件':'正在接收原件'}<p>${hasOriginal?'2026/10/02 13:03 · 已校验':'尚未完成校验'}</p></li><li class="${stage==='saved'?'':'pending'}">${stage==='failed'?'相册处理失败':stage==='saved'?'已保存到 Pixel 相册':'等待加入 Pixel 相册'}<p>${stage==='failed'?'输入结构暂不支持直接封装，原件未删除':stage==='saved'?'2026/10/02 13:04':'保存结果尚未确认'}</p></li><li class="pending">Google 相册云端<p>请在 Google 相册确认，备份鸭不能读取这一状态</p></li></ul>${fileStatus(f)==='failed'?notice('怎么处理？','先重试。仍失败时可查看原因，再决定是否开启兼容转换。','error'):''}`,fileStatus(f)==='failed'?btn('重试处理','retry','refresh','primary'):btn('关闭','close')];}
 if(kind==='pair')return ['连接新设备',`<p>接收服务已启动。请选择要连接的发送端。</p><div class="pair-options"><button class="pair-option" data-action="show-code">${icon('qr')}<span class="grow"><strong>${state.platform==='mac'?'显示 Mac 配对码':'连接 iPhone / iPad'}</strong><p>${state.platform==='mac'?'让 Pixel 扫描下面的配对码':'用 iPhone 扫描 Pixel 的配对码'}</p></span>${icon('chevron')}</button><button class="pair-option" data-action="scan-pair">${icon('scan')}<span class="grow"><strong>${state.platform==='mac'?'查看连接步骤':'连接 Mac'}</strong><p>在 Mac 打开接收设备，显示配对码</p></span>${icon('chevron')}</button></div>`,btn('取消','close')];
 if(kind==='code')return ['扫码配对',`<p>保持两台设备连接同一 Wi-Fi，用${state.platform==='mac'?' Pixel ':' iPhone '}备份鸭扫描。</p><div class="code-card"><div class="qr-demo">${icon('qr')}</div><strong>仅用于演示，不能实际配对</strong><p>真实配对码应有有效期，并可重新生成。</p></div>`,btn('模拟配对成功','paired','check','primary')];
 if(kind==='scan')return ['扫描配对码',`<div class="code-card" style="padding:55px 15px">${icon('scan')}<h4 style="margin:15px 0 7px">在发送端显示配对码</h4><p>让配对码完整落在取景框中。</p></div>${notice('相机未启动','这是设计预览，不会申请或打开你的相机。')}`,btn('模拟扫描成功','paired','check','primary')];
 if(kind==='rules')return ['备份规则',`<p>Canon R62 · 只筛选这个文件夹，不影响其他来源。</p><label class="form-label" for="include">只备份这些文件（白名单）</label><div class="form-help">留空：所有支持的照片和视频都会备份。填写后，只备份符合任意一条规则的文件。</div><textarea id="include" class="rules-input" placeholder="例如：DCIM/**\n例如：**/*.{jpg,JPG,heic,HEIC}"></textarea><label class="form-label" for="exclude">跳过这些文件（黑名单）</label><div class="form-help">符合任意一条规则的文件不会备份。与白名单冲突时，优先跳过。</div><textarea id="exclude" class="rules-input" placeholder="例如：导出/**\n例如：**/临时照片.*"></textarea><details style="margin-top:12px"><summary class="small" style="cursor:pointer;color:var(--blue)">不会写规则？看例子</summary><div class="form-help" style="margin-top:10px">每行一条。<code>旅行/**</code> 表示旅行文件夹下所有内容；<code>**/*.JPG</code> 表示各级文件夹的 JPG 文件。区分大小写。<code>*</code> 不跨文件夹，<code>**</code> 可以跨层级。</div></details>${notice('保存后重新扫描','不删除原文件或已有备份，也不会取消已进入队列的传输。')}`,btn('保存并重新扫描','save-rules','refresh','primary')];
 if(kind==='folder-menu')return ['文件夹操作',`<div class="setting-group">${setting('重新扫描','检查新增和修改的文件，不强制重复上传。','','scan')}${setting('备份规则','设置只备份或跳过哪些文件。','','rules')}${setting('移除来源','从备份来源移除，不删除原文件或已接收的文件。','','remove-source')}</div>`,btn('关闭','close')];
 if(kind==='selected')return ['备份所选照片',`<p>已选择 ${state.selected.size||3} 个项目，其中部分已保存到 Pixel 相册。通常会跳过已备份且未变化的内容。</p><label class="check-option"><input type="checkbox" id="force"><span>重新传输已备份项目<br><span class="small muted">即使已有记录也重新传输，接收端仍会校验。</span></span></label>`,btn('开始备份','confirm-selected','upload','primary')];
 if(kind==='status-guide')return ['传输状态说明',`<div class="setting-group">${Object.entries(statusData).map(([k,v])=>setting(v[0],{queued:'还在队列中，尚未开始传输。',receiving:'原件字节正在传输。',received:'原件已保存并校验，等待相册处理。',saved:'文件已加入 Pixel 系统相册。',failed:'原件已接收，但尚未保存到相册，可重试。'}[k],pill(v[0],v[1],v[2]))).join('')}</div><p>上述状态不等于 Google 相册云端已备份。备份鸭未读取云端状态，因此不把它显示为成功。</p>`,btn('明白了','close')];
 if(kind==='thermal')return ['温度保护',`<p>使用 Pixel 电池传感器读数。超过阈值后暂停接收新内容，降温后按接收端既有恢复逻辑继续。</p><div class="setting-group" style="margin-top:18px">${setting('开启温度保护','关闭后不会因该阈值暂停接收。',toggle('开启温度保护'))}</div><label class="form-label" for="threshold">暂停温度</label><select id="threshold" class="compact-select" style="width:100%">${Array.from({length:11},(_,i)=>i+35).map(v=>`<option ${v===40?'selected':''}>${v} °C${v===40?'（默认）':''}</option>`).join('')}</select>${notice('保护状态可见','发送端和浏览器同步显示“接收端高温暂停”，避免误以为传输失败。')}`,btn('保存','save-setting','','primary')];
 if(kind==='connection')return ['检查连接',`<ul class="timeline"><li>同一 Wi-Fi<p>确认 iPhone / Mac 和 Pixel 在同一个局域网。</p></li><li>接收端已启动<p>打开 Pixel 备份鸭，点“连接新设备”即可启动。</p></li><li>允许本地网络<p>在 iOS 系统设置允许备份鸭访问本地网络。</p></li><li class="pending">仍然连不上？<p>保留配对记录，先重试连接；检查 VPN 或网络隔离。</p></li></ul>`,btn('模拟恢复连接','resume','refresh','primary')];
 if(kind==='web-access')return ['浏览器管理',`<p>在可信任 Wi-Fi 上开启后，电脑可管理这台 Pixel。</p><div class="code-card"><strong>http://192.168.1.120:8485</strong><p>示例地址，当前没有启动真实服务</p></div><label class="form-label" for="access-code">手机上显示的访问码</label><input class="search" id="access-code" inputmode="numeric" style="width:100%" placeholder="输入 10 位访问码" maxlength="10">${notice('仅限可信任的局域网','当前管理页使用 HTTP。关闭接收或浏览器管理后，访问会失效。','warning')}`,btn('模拟登录 / 确认','web-login','lock','primary')];
 if(kind==='storage-detail')return ['存储明细',`<div class="setting-group">${setting('已保留原件','11.5 GB · 可供相册处理重试',pill('保留','ok'))}${setting('处理中与派生文件','5.1 GB · 包含实况封装副本',pill('本机','neutral'))}${setting('相册处理失败','2 个 · 25.2 MB',pill('可重试','warn'),'failed')}</div><p>此设计提案不提供依据本地“已保存”状态删除原件的快捷操作。</p>`,btn('关闭','close')];
 if(kind==='remove-source')return ['移除文件夹来源？',`<p>停止检查这个文件夹的新增内容。原文件、已排队任务和已接收文件不会被删除。</p>`,btn('移除来源（演示）','removed','','danger')];
 if(kind==='rename')return ['设备名称',`<p>这个名称会显示在配对和设备页面。</p><label class="form-label" for="device-name">名称</label><input id="device-name" class="search" style="width:100%" value="Pixel XL" maxlength="32">`,btn('保存','save-setting','','primary')];
 return ['设计操作预览',`<p>${esc(data||'此处演示界面反馈，实际配置仍以应用实现为准。')}</p>`,btn('知道了','close')];}
function renderModal(){const host=$('#modal-host');if(!host||!state.modal)return;const [title,body,foot]=modalContent(state.modal.kind,state.modal.data);host.innerHTML=`<div class="overlay" data-overlay><section class="dialog" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><div class="dialog-head"><h3 id="dialog-title">${title}</h3><button class="icon-btn" data-action="close" aria-label="关闭">${icon('close')}</button></div><div class="dialog-body">${body}</div><div class="dialog-foot">${foot}</div></section></div>`;[...host.parentElement.children].filter(n=>n!==host).forEach(n=>{n.inert=true;n.dataset.modalAria=n.getAttribute('aria-hidden')||'';n.setAttribute('aria-hidden','true')});requestAnimationFrame(()=>host.querySelector('button')?.focus());}
let toastTimer;function showToast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2600)}
function navigate(page){state.page=page;state.folder=false;state.filter='all';state.query='';state.tablePage=1;state.modal=null;render()}
function action(a){if(a.startsWith('go-')){const p=a.slice(3);navigate(p==='receiver'&&state.platform==='android'?'receive':p);return}switch(a){
 case 'home':state.review='screens';render();break;
 case 'theme':{const dark=document.documentElement.dataset.theme!=='dark';document.documentElement.dataset.theme=dark?'dark':'light';$('.review-theme span').textContent=dark?'浅色':'深色';break}
 case 'small':state.small=!state.small;render();break;
 case 'close':{state.modal=null;const host=$('#modal-host');if(host){[...host.parentElement.children].filter(n=>n!==host).forEach(n=>{n.inert=false;if(n.dataset.modalAria)n.setAttribute('aria-hidden',n.dataset.modalAria);else n.removeAttribute('aria-hidden');delete n.dataset.modalAria});host.replaceChildren()}modalTrigger?.focus();break;}
 case 'loaded':state.scene='active';render();break;
 case 'select':state.selecting=!state.selecting;render();break;
 case 'backup-selected':if(!state.selected.size){showToast('先选几张照片，再备份所选。');break}openModal('selected');break;
 case 'confirm-selected':{const force=$('#force')?.checked;state.modal=null;state.scene='active';navigate('backup');showToast(force?'演示：所选项目已加入重新传输队列。':'演示：跳过已备份内容，其余加入队列。');break}
 case 'folder-detail':state.folder=true;render();break;
 case 'folder-back':state.folder=false;render();break;
 case 'flat':state.tree=false;render();break;
 case 'tree':state.tree=true;state.treeOpen=true;render();break;
 case 'tree-expand':state.treeOpen=!state.treeOpen;render();break;
 case 'folder-menu':openModal('folder-menu');break;
 case 'rules':openModal('rules');break;
 case 'save-rules':state.modal=null;render();showToast('演示：规则已保存，正在重新扫描。');break;
 case 'scan':state.modal=null;if(state.scene==='disk'){render();showToast('SD 卡未连接，请插回后再扫描。')}else{render();showToast('演示：扫描完成，已备份且未变化的文件会跳过。')}break;
 case 'backup-existing':showToast('演示：新增与失败文件加入队列；未变化的已备份文件跳过。');break;
 case 'add-folder':openModal('generic','真实应用中会打开系统文件夹选择器，可选择 SD 卡、电脑或外置硬盘。');break;
 case 'pair':openModal('pair');break;
 case 'show-code':openModal('code');break;
 case 'scan-pair':openModal('scan');break;
 case 'paired':state.modal=null;state.scene='active';render();showToast('演示：配对成功，接收服务已启动。');break;
 case 'start':case 'resume':state.modal=null;state.scene='active';render();showToast('演示：已恢复接收与传输。');break;
 case 'pause':state.scene='paused';state.modal=null;render();showToast('演示：传输已暂停，点继续恢复；原件保持不变。');break;
 case 'failed':state.modal=null;state.page='transfers';state.filter='failed';render();break;
 case 'retry':state.modal=null;render();showToast('演示：失败原件已请求重新处理，成功前仍显示失败。');break;
 case 'status-guide':openModal('status-guide');break;
 case 'thermal-settings':openModal('thermal');break;
 case 'connection':case 'receive-help':openModal('connection');break;
 case 'web-access':openModal('web-access');break;
 case 'web-login':state.modal=null;state.scene='active';render();showToast('演示：访问码验证通过。');break;
 case 'refresh':showToast('演示数据已刷新，保留当前分页与筛选。');break;
 case 'rename':openModal('rename');break;
 case 'save-setting':state.modal=null;render();showToast('演示：设置已保存。');break;
 case 'remove-source':openModal('remove-source');break;
 case 'removed':state.modal=null;render();showToast('演示：来源已移除，原文件没有删除。');break;
 case 'storage-detail':openModal('storage-detail');break;
 case 'clear-filter':state.filter='all';state.query='';render();break;
 case 'motion-sheet':$('#demo-sheet')?.classList.toggle('visible');break;
 case 'permission':state.scene='active';render();showToast('演示：已获得照片权限。');break;
 case 'updates':openModal('generic','检查更新应分别展示检查中、可更新、已是最新和网络失败；不能把检查失败误报成“开发版本”。');break;
 case 'storage-limit':openModal('generic','原件空间上限与可用空间都影响接收。到达上限显示原因，不静默丢弃文件。');break;
 case 'list-view':openModal('generic','在 macOS 文件夹详情切换平铺 / 按文件夹。两种模式均显示文件时间。');break;
 default:showToast('这是设计控件演示，不更改真实应用设置。');
}}
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(b){if(b.dataset.action){e.preventDefault();if(b.dataset.action==='toggle'){const on=b.getAttribute('aria-checked')!=='true';b.setAttribute('aria-checked',on);b.classList.toggle('on',on);return}action(b.dataset.action)}else if(b.dataset.review){state.review=b.dataset.review;state.modal=null;render()}else if(b.dataset.platform){state.platform=b.dataset.platform;state.page=defaults[state.platform];state.filter='all';state.folder=false;state.modal=null;state.query='';render()}else if(b.dataset.page){navigate(b.dataset.page)}else if(b.dataset.filter){state.filter=b.dataset.filter;state.tablePage=1;render()}else if(b.dataset.file!==undefined){openModal('detail',Number(b.dataset.file))}else if(b.dataset.photo!==undefined){const n=Number(b.dataset.photo);if(state.selecting){state.selected.has(n)?state.selected.delete(n):state.selected.add(n);render()}else openModal('detail',n)}else if(b.dataset.tablePage){state.tablePage=Number(b.dataset.tablePage);render()}else if(b.dataset.motion){motionMode=b.dataset.motion;render()}}if(e.target.matches('[data-overlay]'))action('close')});
document.addEventListener('change',e=>{const c=e.target.dataset.control;if(c==='scene'){state.scene=e.target.value;state.modal=null;render()}if(c==='material'){state.material=e.target.value;render()}if(c==='transparency'){state.reducedTransparency=e.target.checked;render()}if(c==='sort'){state.sort=e.target.value;render()}if(c==='page-size'){state.pageSize=Number(e.target.value);state.tablePage=1;render()}if(c==='jump-page'){const max=Math.max(1,Math.ceil(filtered().length/state.pageSize));state.tablePage=Math.min(max,Math.max(1,Number(e.target.value)||1));render()}});
document.addEventListener('input',e=>{if(e.target.dataset.control==='search'){state.query=e.target.value;state.tablePage=1;const start=e.target.selectionStart;render();const field=$('[data-control="search"]');field?.focus();field?.setSelectionRange(start,start)}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&state.modal){action('close');return}if(e.key==='Tab'&&state.modal){const nodes=[...document.querySelectorAll('.dialog button,.dialog a,.dialog input,.dialog textarea,.dialog select,.dialog summary')].filter(n=>!n.disabled);const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}});
render();
